values ('ally_flint', 'FLINT_BLAZER', 'Flint Blazer', 'Common', 'DPS', 'A Legion field artillerist who was dishonourably discharged for firing an experimental forge-cannon at superior officers during a retreat order he deemed tactically unsound. He was right — and three hundred soldiers survived because of it. He has never apologised.', 'Forge Canyon Depths', 'STARFORGED_LEGION', '{"hp": 95, "mp": 70, "atk": 120, "def": 75, "agi": 100, "per": 90}'::jsonb, 'al_flint_pas', 'al_flint_act', 1, 40, 1.0, 1, 18)
