values ('ally_elara', 'ELARA_VOSS', 'Elara Voss', 'Legendary', 'Support', 'A Concordium high councillor who willingly stripped herself of rank and position to enter the field when she realised bureaucracy was losing the war against the Void. Elara Voss is the most dangerous thing in any battle she enters — not because she fights, but because everyone around her fights better.', 'Nexus Core', 'CONCORDIUM', '{"hp": 120, "mp": 180, "atk": 70, "def": 100, "agi": 110, "per": 170}'::jsonb, 'al_elara_pas', 'al_elara_act', 3, 70, 0.72, 4, 19)
