values ('ally_cipher', 'CIPHER_VELL', 'Cipher Vell', 'Uncommon', 'DPS', 'A code-breaker from the Concordium intelligence division who repurposed her decryption skills for combat. She fights the same way she cracks encryption — find the weakness, exploit it, move on before anyone notices.', 'Nexus Core', 'CONCORDIUM', '{"hp": 85, "mp": 90, "atk": 118, "def": 68, "agi": 122, "per": 105}'::jsonb, 'al2_cipher_pas', 'al2_cipher_act', 1, 45, 0.97, 1, 21)
