values ('ally_wren', 'WREN_ECHO', 'Wren Echo', 'Rare', 'Support', 'A former Arcanum communications analyst who discovered she could perceive emotional resonance in teammates — and tune it. Her battlefield role is part strategist, part therapist, entirely indispensable.', 'Observatory Spire', 'THE_ARCANUM_SEEKERS', '{"hp": 90, "mp": 145, "atk": 60, "def": 80, "agi": 100, "per": 138}'::jsonb, 'al2_wren_pas', 'al2_wren_act', 2, 50, 0.93, 2, 22)
