values ('ally_ashe', 'ASHE_MERIDIAN', 'Ashe Meridian', 'Legendary', 'DPS', 'The Arcanum Seekers consider Ashe a failure — her power exceeded their ability to measure it, and she refused containment. She walks the ley-lines alone now, drawn to conflict the way storms are drawn to open plains.', 'Fractured Glass Valley', 'THE_ARCANUM_SEEKERS', '{"hp": 100, "mp": 185, "atk": 85, "def": 70, "agi": 105, "per": 175}'::jsonb, 'al2_ashe_pas', 'al2_ashe_act', 3, 70, 0.72, 4, 23)
