values ('ally_rook', 'ROOK_HALLAM', 'Rook Hallam', 'Common', 'DPS', 'A demolitions specialist from the Scrap Field who was too effective at his job — kept blowing up things the Hegemony wanted to keep. Now freelance, he applies the same methodical approach to enemies as he did to structures.', 'Scrap Field', 'IRON_HEGEMONY', '{"hp": 95, "mp": 60, "atk": 125, "def": 80, "agi": 100, "per": 88}'::jsonb, 'al2_rook_pas', 'al2_rook_act', 1, 40, 1.0, 1, 24)
