values ('ally_vale', 'VALE_SOLIS', 'Vale Solis', 'Rare', 'Healer', 'A Cartel field medic who learned combat medicine on dockside jobs where there were no hospitals for miles. Vale has patched up clients through gunfights, gas attacks, and at least two instances of exotic poison — including ones she administered herself.', 'Port Meridian', 'MERIDIAN_CARTEL', '{"hp": 108, "mp": 148, "atk": 58, "def": 88, "agi": 90, "per": 140}'::jsonb, 'al2_vale_pas', 'al2_vale_act', 2, 50, 0.93, 2, 25)
