values ('ally_tide', 'TIDE_VARREN', 'Tide Varren', 'Uncommon', 'DPS', 'Grew up hunting in the Coral Wetlands before the Cartel claimed it. Tide knows every current, every blind spot, every place something can disappear. He applies the same knowledge to tracking people.', 'Coral Wetlands', 'MERIDIAN_CARTEL', '{"hp": 88, "mp": 75, "atk": 120, "def": 70, "agi": 128, "per": 92}'::jsonb, 'al2_tide_pas', 'al2_tide_act', 1, 45, 0.97, 1, 26)
