values ('ally_axiom', 'AXIOM_UNIT', 'Axiom-7', 'Epic', 'DPS', 'A combat drone unit upgraded beyond its original parameters by its assigned engineer — who then filed the paperwork wrong, creating a legally autonomous entity. Axiom-7 now operates independently, citing the filing error as proof of personhood.', 'Extraction Zone Delta', 'OMNICORP', '{"hp": 95, "mp": 110, "atk": 158, "def": 75, "agi": 130, "per": 120}'::jsonb, 'al2_axiom_pas', 'al2_axiom_act', 2, 55, 0.83, 3, 27)
