values ('ally_prism', 'PRISM_HARLOW', 'Prism Harlow', 'Epic', 'Support', 'An OmniCorp systems architect who built the Spire''s defensive grid and now deploys the same principles in the field. Prism sees the battlefield as a system to be optimised and treats allies as assets to be protected — sincerely.', 'The Spire', 'OMNICORP', '{"hp": 105, "mp": 138, "atk": 65, "def": 100, "agi": 95, "per": 145}'::jsonb, 'al2_prism_pas', 'al2_prism_act', 2, 55, 0.83, 3, 28)
