values ('ally_nimbus', 'NIMBUS_SOL', 'Nimbus Sol', 'Common', 'Support', 'A young acolyte who was too eager for the Sanctum''s pace and too undisciplined for high ritual. Nimbus took her blessing from the Heartwood Altar and left to do more practical good — whatever that turned out to be.', 'Glowvine Forest', 'CHILDREN_OF_THE_SHARD', '{"hp": 80, "mp": 130, "atk": 55, "def": 78, "agi": 92, "per": 125}'::jsonb, 'al2_nimbus_pas', 'al2_nimbus_act', 1, 40, 1.0, 1, 29)
