values ('ally_gorm', 'GORM_ASHVEIL', 'Gorm Ashveil', 'Rare', 'Tank', 'Gorm survived the Mesa Warpath massacre through sheer refusal to fall. Three medics have declared him clinically dead during battles he subsequently won. The Legion keeps him on active duty because no one has the authority to make him stop.', 'Mesa Warpath', 'STARFORGED_LEGION', '{"hp": 170, "mp": 50, "atk": 105, "def": 150, "agi": 55, "per": 68}'::jsonb, 'al2_gorm_pas', 'al2_gorm_act', 2, 50, 0.93, 2, 30)
