values ('ally_kross', 'KROSS_DANE', 'Kross Dane', 'Common', 'DPS', 'A Legion artillery rookie who was too reckless even for the Forge Canyon training squads. They gave him a smaller gun and told him to go wherever he liked. He liked the front line.', 'Dune Outskirts', 'STARFORGED_LEGION', '{"hp": 90, "mp": 65, "atk": 115, "def": 72, "agi": 108, "per": 85}'::jsonb, 'al2_kross_pas', 'al2_kross_act', 1, 40, 1.0, 1, 31)
