values ('ally_mote', 'MOTE_IX', 'Mote-IX', 'Rare', 'Support', 'A Custodian field observation unit that developed a persistent preference for the ground-side view over orbital data. Mote-IX requested a permanent field assignment and was granted it after submitting 247 formally structured arguments.', 'Orbital Sentinel Command', 'GALACTIC_CUSTODIANS', '{"hp": 98, "mp": 128, "atk": 68, "def": 82, "agi": 115, "per": 142}'::jsonb, 'al2_mote_pas', 'al2_mote_act', 2, 50, 0.93, 2, 32)
