values ('ally_lyric', 'LYRIC_SEVEN', 'Lyric-VII', 'Common', 'Healer', 'A Custodian medical assistant unit that specialised in harmonic resonance therapy. Lyric-VII left orbital service after determining that field personnel had statistically worse outcomes than they would under her direct care.', 'Orbital Sentinel Command', 'GALACTIC_CUSTODIANS', '{"hp": 100, "mp": 140, "atk": 48, "def": 85, "agi": 82, "per": 132}'::jsonb, 'al2_lyric_pas', 'al2_lyric_act', 1, 40, 1.0, 1, 33)
