values ('ally_pascal', 'PASCAL_VOID', 'Pascal Void', 'Epic', 'DPS', 'A Custodian tactical analyst who underwent an experimental Void-channelling enhancement that left half his neural map mapped to null-space. Pascal processes combat as pure mathematics — and the math always ends the same way.', 'Orbital Sentinel Command', 'GALACTIC_CUSTODIANS', '{"hp": 95, "mp": 150, "atk": 90, "def": 72, "agi": 115, "per": 162}'::jsonb, 'al3_pascal_pas', 'al3_pascal_act', 2, 55, 0.83, 3, 34)
