values ('ally_rekha', 'REKHA_IRON', 'Rekha Ironhand', 'Uncommon', 'Healer', 'A Hegemony combat medic who served six tours across the border campaigns. Rekha has more battlefield hours than most field commanders and more scars than she''ll admit to. She heals first, asks questions never.', 'Iron Ravine', 'IRON_HEGEMONY', '{"hp": 105, "mp": 138, "atk": 55, "def": 90, "agi": 85, "per": 130}'::jsonb, 'al3_rekha_pas', 'al3_rekha_act', 1, 45, 0.97, 1, 35)
