values ('ally_reva', 'REVA_DUSK', 'Reva Dusk', 'Common', 'DPS', 'Born in the Scrap Fields where Iron Hegemony conscription crews made monthly sweeps, Reva learned to shoot before she could read — aiming at anything that moved through rusted debris kept her alive when the drafters came. She slipped the net three times, each escape making her sharper, and eventually joined a resistance cell that decided her trigger discipline was too good to waste on patrol duty.', 'Scrap Fields, Iron Belt', 'IRON_HEGEMONY', '{"hp": 88, "mp": 72, "atk": 118, "def": 70, "agi": 122, "per": 92}'::jsonb, 'al5_62_pas', 'al5_62_act', 1, 40, 1.0, 1, 61)
on conflict (ally_id) do update set code=excluded.code, name=excluded.name, rarity=excluded.rarity, role=excluded.role, brief_background_story=excluded.brief_background_story, place_of_origin=excluded.place_of_origin, faction_affinity=excluded.faction_affinity, base_stats=excluded.base_stats, passive_skill_id=excluded.passive_skill_id, active_skill_id=excluded.active_skill_id, recruit_cost=excluded.recruit_cost, level_cap=excluded.level_cap, pvp_scale=excluded.pvp_scale, conclave_points=excluded.conclave_points, sort_order=excluded.sort_order;
