values ('ally_grak', 'GRAK_PELL', 'Grak Pell', 'Common', 'Tank', 'Grak spent thirty-two years as a Concordium checkpoint guard at Sector 9''s eastern crossing, turning back smugglers and breaking up brawls with the same unhurried calm. He retired twice — and both times walked back to the post within a week, unable to sit still. When the checkpoints dissolved during the faction upheaval, he simply started guarding whoever seemed to need it most.', 'Sector 9 Crossing, Concordium Territory', 'CONCORDIUM', '{"hp": 152, "mp": 50, "atk": 88, "def": 130, "agi": 58, "per": 68}'::jsonb, 'al5_63_pas', 'al5_63_act', 1, 40, 1.0, 1, 62)
