values ('ally_torr', 'TORR_ASHFELD', 'Torr Ashfeld', 'Common', 'DPS', 'Torr spent a decade feeding the Legion''s blast furnaces at the Ashfeld Foundry, shoveling slag and breathing superheated air until it stopped bothering him. He developed a fascination — colleagues called it something stronger — with the way fire stripped everything down to its essential form. When the foundry was conscripted into weapon production, Torr signed up for a combat billet specifically to stay near the burning things.', 'Ashfeld Foundry, Starforged Legion', 'STARFORGED_LEGION', '{"hp": 90, "mp": 65, "atk": 120, "def": 78, "agi": 108, "per": 82}'::jsonb, 'al5_66_pas', 'al5_66_act', 1, 40, 1.0, 1, 65)
