values ('ally_narra', 'NARRA_COLE', 'Narra Cole', 'Common', 'Healer', 'Narra ran the Meridian Cartel''s dockside dispensary for six years, no questions asked about who was bleeding or why. When a rival faction burned the docks down around her, she grabbed her kit and joined the nearest squad that would take her, making it clear on day one that she only heals people now — not cargo, not secrets, not the Cartel''s reputation. The distinction matters to her.', 'Port Meridian, Cartel Docks', 'MERIDIAN_CARTEL', '{"hp": 100, "mp": 136, "atk": 46, "def": 82, "agi": 80, "per": 122}'::jsonb, 'al5_67_pas', 'al5_67_act', 1, 40, 1.0, 1, 66)
