insert into public.allies (ally_id, code, name, rarity, role, brief_background_story, place_of_origin, faction_affinity, base_stats, passive_skill_id, active_skill_id, recruit_cost, level_cap, pvp_scale, conclave_points, sort_order)
values ('ally_zax', 'ZAX_VOLT', 'Zax Volt', 'Common', 'DPS', 'Zax attempted the Arcanum Seekers entrance examination three times, failing the theoretical component on each attempt despite demonstrating an instinctive grasp of aether channeling that examiners described as ''impressively dangerous.'' Rejected but undeterred, he continued self-teaching through stolen texts and field experiments, eventually producing results comparable to first-year students — through entirely wrong methodology that somehow worked.', 'Outer Relay Station, Arcanum Fringe', 'THE_ARCANUM_SEEKERS', '{"hp": 85, "mp": 78, "atk": 112, "def": 68, "agi": 118, "per": 96}'::jsonb, 'al5_68_pas', 'al5_68_act', 1, 40, 1.0, 1, 67)
