values ('ally_brom', 'BROM_HULL', 'Brom Hull', 'Common', 'Tank', 'Commander Hull once led a four-hundred-soldier labor battalion, coordinating fortification construction across three active sectors. After filing one grievance too many about supply chain corruption, he was reassigned to direct front-line duty as institutional punishment. Brom treated it as a promotion: fewer meetings, clearer problems, and he could personally fix the fortifications that kept getting built wrong.', 'Bastion Core, Iron Hegemony', 'IRON_HEGEMONY', '{"hp": 155, "mp": 52, "atk": 92, "def": 138, "agi": 56, "per": 70}'::jsonb, 'al5_69_pas', 'al5_69_act', 1, 40, 1.0, 1, 68)
