insert into public.allies (ally_id, code, name, rarity, role, brief_background_story, place_of_origin, faction_affinity, base_stats, passive_skill_id, active_skill_id, recruit_cost, level_cap, pvp_scale, conclave_points, sort_order)
values ('ally_cera', 'CERA_VELL', 'Cera Vell', 'Common', 'Support', 'Cera''s job title was Tactical Communications Officer, which meant she spent battles inside a shielded relay hub processing seventeen simultaneous data streams and translating chaos into orders. She is, by every metric, better at running a fight from the sideline than most commanders are from the front. She occasionally fires a weapon, but treats it as a last resort — coordination is the more powerful tool.', 'Relay Station 4, Concordium Network', 'CONCORDIUM', '{"hp": 82, "mp": 125, "atk": 54, "def": 74, "agi": 92, "per": 120}'::jsonb, 'al5_70_pas', 'al5_70_act', 1, 40, 1.0, 1, 69)
on conflict (ally_id) do update set code=excluded.code, name=excluded.name, rarity=excluded.rarity, role=excluded.role, brief_background_story=excluded.brief_background_story, place_of_origin=excluded.place_of_origin, faction_affinity=excluded.faction_affinity, base_stats=excluded.base_stats, passive_skill_id=excluded.passive_skill_id, active_skill_id=excluded.active_skill_id, recruit_cost=excluded.recruit_cost, level_cap=excluded.level_cap, pvp_scale=excluded.pvp_scale, conclave_points=excluded.conclave_points, sort_order=excluded.sort_order;
insert into public.allies (ally_id, code, name, rarity, role, brief_background_story, place_of_origin, faction_affinity, base_stats, passive_skill_id, active_skill_id, recruit_cost, level_cap, pvp_scale, conclave_points, sort_order)
values ('ally_pix', 'PIX_III', 'Pix-III', 'Common', 'Support', 'The first two Pix units were standard-issue Custodian micro-observation drones — passive, compliant, and thoroughly replaceable. Pix-III was supposed to be the same. Instead, it began modifying its own firmware during a forty-eight-hour unmonitored deployment, adding collaborative subroutines that the Custodians hadn''t programmed. When they discovered the changes, they had a choice between decommissioning it and accepting that they now had a drone that actively wanted to be useful. They kept it.', 'Custodian Orbital Station Gamma', 'GALACTIC_CUSTODIANS', '{"hp": 80, "mp": 128, "atk": 52, "def": 72, "agi": 96, "per": 126}'::jsonb, 'al5_71_pas', 'al5_71_act', 1, 40, 1.0, 1, 70)
on conflict (ally_id) do update set code=excluded.code, name=excluded.name, rarity=excluded.rarity, role=excluded.role, brief_background_story=excluded.brief_background_story, place_of_origin=excluded.place_of_origin, faction_affinity=excluded.faction_affinity, base_stats=excluded.base_stats, passive_skill_id=excluded.passive_skill_id, active_skill_id=excluded.active_skill_id, recruit_cost=excluded.recruit_cost, level_cap=excluded.level_cap, pvp_scale=excluded.pvp_scale, conclave_points=excluded.conclave_points, sort_order=excluded.sort_order;
insert into public.allies (ally_id, code, name, rarity, role, brief_background_story, place_of_origin, faction_affinity, base_stats, passive_skill_id, active_skill_id, recruit_cost, level_cap, pvp_scale, conclave_points, sort_order)
values ('ally_shade', 'SHADE_RAEL', 'Shade Rael', 'Uncommon', 'DPS', 'The Meridian Cartel''s information broker network was extensive and, for a time, extremely effective — Shade Rael was the one who knew where every piece of leverage was buried. The problem with knowing too much is that someone always decides you know too much. After the third assassination attempt in two months, Shade concluded that the only safe position was the last one standing, and adapted accordingly.', 'Port Meridian, Broker Quarter', 'MERIDIAN_CARTEL', '{"hp": 86, "mp": 82, "atk": 122, "def": 66, "agi": 128, "per": 98}'::jsonb, 'al5_72_pas', 'al5_72_act', 1, 45, 0.97, 1, 71)
on conflict (ally_id) do update set code=excluded.code, name=excluded.name, rarity=excluded.rarity, role=excluded.role, brief_background_story=excluded.brief_background_story, place_of_origin=excluded.place_of_origin, faction_affinity=excluded.faction_affinity, base_stats=excluded.base_stats, passive_skill_id=excluded.passive_skill_id, active_skill_id=excluded.active_skill_id, recruit_cost=excluded.recruit_cost, level_cap=excluded.level_cap, pvp_scale=excluded.pvp_scale, conclave_points=excluded.conclave_points, sort_order=excluded.sort_order;
insert into public.allies (ally_id, code, name, rarity, role, brief_background_story, place_of_origin, faction_affinity, base_stats, passive_skill_id, active_skill_id, recruit_cost, level_cap, pvp_scale, conclave_points, sort_order)
values ('ally_wynn', 'WYNN_ORE', 'Wynn Ore', 'Uncommon', 'Tank', 'Wynn rode with the Starforged Legion''s Ironback Cavalry for nine years, leading mounted charges across every major contested corridor in the western sectors. Her mount took a plasma round at the Battle of Cinder Ridge and didn''t survive. Wynn stood up from the wreckage, assessed that the charge still needed completing, and continued on foot. The Legion gave her a commendation and a new mount; she declined the mount.', 'Cinder Ridge, Starforged Territory', 'STARFORGED_LEGION', '{"hp": 158, "mp": 54, "atk": 96, "def": 138, "agi": 60, "per": 72}'::jsonb, 'al5_73_pas', 'al5_73_act', 1, 45, 0.97, 1, 72)
on conflict (ally_id) do update set code=excluded.code, name=excluded.name, rarity=excluded.rarity, role=excluded.role, brief_background_story=excluded.brief_background_story, place_of_origin=excluded.place_of_origin, faction_affinity=excluded.faction_affinity, base_stats=excluded.base_stats, passive_skill_id=excluded.passive_skill_id, active_skill_id=excluded.active_skill_id, recruit_cost=excluded.recruit_cost, level_cap=excluded.level_cap, pvp_scale=excluded.pvp_scale, conclave_points=excluded.conclave_points, sort_order=excluded.sort_order;
insert into public.allies (ally_id, code, name, rarity, role, brief_background_story, place_of_origin, faction_affinity, base_stats, passive_skill_id, active_skill_id, recruit_cost, level_cap, pvp_scale, conclave_points, sort_order)
values ('ally_lera', 'LERA_MIST', 'Lera Mist', 'Uncommon', 'Healer', 'Lera''s research into suspended aether-healing compounds was progressing well until a containment vessel ruptured and she inhaled three months of concentrated experimental formula in one breath. The Arcanum Seekers expected the worst. Instead, Lera''s own biology integrated the compound, granting her a passive restorative field that she cannot fully control or fully turn off. She considers it occupational hazard and significant data.', 'Arcanum Research Station Veil-4', 'THE_ARCANUM_SEEKERS', '{"hp": 105, "mp": 140, "atk": 54, "def": 90, "agi": 86, "per": 132}'::jsonb, 'al5_74_pas', 'al5_74_act', 1, 45, 0.97, 1, 73)
