values ('ally_lysa', 'LYSA_BLOOM', 'Lysa Bloom', 'Uncommon', 'Healer', 'The Monastery of the Unbroken Root was attacked three times during the Shard Wars — twice by factions wanting its sacred garden destroyed, once by a faction wanting it seized. Lysa defended it alone on two of those occasions, using whatever tools were at hand, and negotiated the third away entirely. The garden survived all three. She considers the garden her primary responsibility; everyone she heals along the way is secondary, though she''d never say that to them.', 'Monastery of the Unbroken Root, Shard Reaches', 'CHILDREN_OF_THE_SHARD', '{"hp": 108, "mp": 144, "atk": 56, "def": 92, "agi": 88, "per": 136}'::jsonb, 'al5_78_pas', 'al5_78_act', 1, 45, 0.97, 1, 77)
