values ('ally_torrak', 'TORRAK_IRON', 'Torrak Iron', 'Epic', 'Tank', 'The Void incursion at Bastion Redoubt lasted nine hours. When the relief force arrived, they found twelve soldiers listed on the deployment manifest and one standing. Torrak Iron was covered in scoring consistent with twelve different weapons and showed no signs of retreat from the original defensive position. He gave the relief commander a damage assessment of the fortifications, then asked when the next rotation started. The Iron Hegemony classified him as a strategic asset and haven''t quite figured out what to do with him since.', 'Bastion Redoubt, Iron Hegemony Frontier', 'IRON_HEGEMONY', '{"hp": 198, "mp": 62, "atk": 115, "def": 175, "agi": 54, "per": 80}'::jsonb, 'al5_87_pas', 'al5_87_act', 2, 55, 0.83, 3, 86)
on conflict (ally_id) do update set code=excluded.code, name=excluded.name, rarity=excluded.rarity, role=excluded.role, brief_background_story=excluded.brief_background_story, place_of_origin=excluded.place_of_origin, faction_affinity=excluded.faction_affinity, base_stats=excluded.base_stats, passive_skill_id=excluded.passive_skill_id, active_skill_id=excluded.active_skill_id, recruit_cost=excluded.recruit_cost, level_cap=excluded.level_cap, pvp_scale=excluded.pvp_scale, conclave_points=excluded.conclave_points, sort_order=excluded.sort_order;
insert into public.allies (ally_id, code, name, rarity, role, brief_background_story, place_of_origin, faction_affinity, base_stats, passive_skill_id, active_skill_id, recruit_cost, level_cap, pvp_scale, conclave_points, sort_order)
values ('ally_caelan', 'CAELAN_ARC', 'Caelan Arc', 'Epic', 'Healer', 'On the first day of the Shard War''s expansion phase, Caelan Arc filed an administrative declaration classifying the entire conflict as a sustained emergency under Galactic Custodian Emergency Protocol 7. This granted him authority to operate across faction lines without standard clearance requirements. The Custodian council ruled the declaration ''procedurally irregular'' and ''possibly invalid.'' Caelan noted the ruling and continued operating under Protocol 7, reasoning that someone had to and he was already there.', 'Custodian Emergency Response Command', 'GALACTIC_CUSTODIANS', '{"hp": 118, "mp": 172, "atk": 54, "def": 98, "agi": 90, "per": 165}'::jsonb, 'al5_88_pas', 'al5_88_act', 2, 55, 0.83, 3, 87)
on conflict (ally_id) do update set code=excluded.code, name=excluded.name, rarity=excluded.rarity, role=excluded.role, brief_background_story=excluded.brief_background_story, place_of_origin=excluded.place_of_origin, faction_affinity=excluded.faction_affinity, base_stats=excluded.base_stats, passive_skill_id=excluded.passive_skill_id, active_skill_id=excluded.active_skill_id, recruit_cost=excluded.recruit_cost, level_cap=excluded.level_cap, pvp_scale=excluded.pvp_scale, conclave_points=excluded.conclave_points, sort_order=excluded.sort_order;
insert into public.allies (ally_id, code, name, rarity, role, brief_background_story, place_of_origin, faction_affinity, base_stats, passive_skill_id, active_skill_id, recruit_cost, level_cap, pvp_scale, conclave_points, sort_order)
values ('ally_lyssa', 'LYSSA_VOID', 'Lyssa Void', 'Epic', 'Support', 'Lyssa did not choose to become a Void-walker — she was pulled through a spatial rupture during a battle that erased the unit around her and left her alone in null-space with no extraction protocol and no training. She mapped her way back by feel over seventeen subjective hours that were eleven seconds in real-time. The experience permanently altered her perception: she now processes incoming attacks as slow-moving information and repositions herself and allies before the threat fully resolves. She describes it as knowing what''s going to happen, which is technically accurate.', 'Null-Space Rupture Zone, Location Unknown', 'NONE', '{"hp": 100, "mp": 155, "atk": 68, "def": 100, "agi": 112, "per": 162}'::jsonb, 'al5_89_pas', 'al5_89_act', 2, 55, 0.83, 3, 88)
on conflict (ally_id) do update set code=excluded.code, name=excluded.name, rarity=excluded.rarity, role=excluded.role, brief_background_story=excluded.brief_background_story, place_of_origin=excluded.place_of_origin, faction_affinity=excluded.faction_affinity, base_stats=excluded.base_stats, passive_skill_id=excluded.passive_skill_id, active_skill_id=excluded.active_skill_id, recruit_cost=excluded.recruit_cost, level_cap=excluded.level_cap, pvp_scale=excluded.pvp_scale, conclave_points=excluded.conclave_points, sort_order=excluded.sort_order;
insert into public.allies (ally_id, code, name, rarity, role, brief_background_story, place_of_origin, faction_affinity, base_stats, passive_skill_id, active_skill_id, recruit_cost, level_cap, pvp_scale, conclave_points, sort_order)
values ('ally_aegis', 'AEGIS_PRIME', 'Aegis Prime', 'Legendary', 'Tank', 'Aegis Prime has been online for four hundred years, updating itself through every iteration of Galactic Custodian hardware standards while maintaining continuity of self across twenty-three body replacements. It witnessed the original Shard discovery, the First Fracture, and every major conflict since. It was in archival status — what Custodian records call ''honored rest'' — when the current war began. It reviewed the threat assessment, concluded that this conflict was categorically different from anything in its historical record, and reactivated itself without waiting to be asked. Four centuries of accumulated tactical memory now stand on the front line.', 'Custodian Archive Station Omega', 'GALACTIC_CUSTODIANS', '{"hp": 212, "mp": 78, "atk": 125, "def": 188, "agi": 68, "per": 92}'::jsonb, 'al5_90_pas', 'al5_90_act', 3, 70, 0.72, 4, 89)
